window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ee034651ef5d8875"]={"versions": [{"id": "FIG-ee034651ef5d8875", "releases": ["R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Datentypdefinition im Kontext der AUTOSAR Adaptive Platform (Spezifikation <code>AUTOSAR_SWS_TimeSync</code>). Das Diagramm ist eingebettet in den Modellrahmen <code>class TimeBaseClassModel</code> und definiert die Enumeration zur Kennzeichnung von Synchronisations- und Zeitstatus-Flags für Zeitbasen (<code>TimeBase</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert eine Enumeration:</p>\n<ul class=\"fig-list\">\n<li>Name: <code>StatusFlags</code> (Stereotyp <code>«enumeration»</code>)</li>\n<li>Literale mit expliziter ganzzahliger Belegung:</li>\n<li><code>kTimeOut = 0</code></li>\n<li><code>kSynchronized = 1</code></li>\n<li><code>kSyncToGateway = 2</code></li>\n<li><code>kTimeLeapFuture = 3</code></li>\n<li><code>kTimeLeapPast = 4</code></li>\n<li><code>kHasDLS = 5</code></li>\n<li><code>kDLSActive = 6</code></li>\n</ul>\n<p class=\"fig-p\">Kontextrahmen: Das Element ist im Namensraum/Modellpaket <code>TimeBaseClassModel</code> platziert.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Datenmodell ohne dynamische Interaktion oder Sequenzfluss. Die Literale repräsentieren binäre Zustands- bzw. Ereignisflags (Bitmasken oder Enumerationswerte) des Synchronisationsstatus einer Zeitbasis:</p>\n<ul class=\"fig-list\">\n<li><code>kTimeOut</code> (0): Signalisiert einen Timeout in der Zeitsynchronisation.</li>\n<li><code>kSynchronized</code> (1): Zeitbasis ist synchronisiert.</li>\n<li><code>kSyncToGateway</code> (2): Synchronisation erfolgt zu einem Gateway.</li>\n<li><code>kTimeLeapFuture</code> (3): Zeitsprung in die Zukunft festgestellt.</li>\n<li><code>kTimeLeapPast</code> (4): Zeitsprung in die Vergangenheit festgestellt.</li>\n<li><code>kHasDLS</code> (5): Daylight Saving Time (Sommerzeit) Information vorhanden.</li>\n<li><code>kDLSActive</code> (6): Daylight Saving Time (Sommerzeit) ist aktiv.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative C++-Datentypspezifikation für die Adaptive Platform Time Synchronization. Die Enumerationswerte definieren feste numerische Werte (0 bis 6), die bei Statusabfragen oder Callbacks der Time-Base-Klassen verwendet werden. Entwickler müssen die Literale typkonform als Enum-Werte zur Statuserfassung und Fehlerbehandlung der Zeitsynchronisation auswerten.</p>"}, {"id": "FIG-7ac4ab1084ae69e9", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Datentypdefinition im Kontext der AUTOSAR Adaptive Platform (Spezifikation <code>AUTOSAR_SWS_TimeSync</code>). Das Diagramm definiert als eigenständiges Element die Enumeration zur Kennzeichnung von Synchronisations- und Zeitstatus-Flags für Zeitbasen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert eine Enumeration:</p>\n<ul class=\"fig-list\">\n<li>Name: <code>StatusFlag</code> (Stereotyp <code>«enum»</code>)</li>\n<li>Literale mit expliziter ganzzahliger Belegung:</li>\n<li><code>kTimeOut = 0</code></li>\n<li><code>kSynchronized = 1</code></li>\n<li><code>kSyncToGateway = 2</code></li>\n<li><code>kTimeLeapFuture = 3</code></li>\n<li><code>kTimeLeapPast = 4</code></li>\n<li><code>kHasDLS = 5</code></li>\n<li><code>kDLSActive = 6</code></li>\n</ul>\n<p class=\"fig-p\">Das Element steht eigenständig ohne umschließenden Klassendiagramm-Rahmen.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Datenmodell ohne dynamische Interaktion oder Sequenzfluss. Die Literale repräsentieren binäre Zustands- bzw. Ereignisflags (Bitmasken oder Enumerationswerte) des Synchronisationsstatus einer Zeitbasis:</p>\n<ul class=\"fig-list\">\n<li><code>kTimeOut</code> (0): Signalisiert einen Timeout in der Zeitsynchronisation.</li>\n<li><code>kSynchronized</code> (1): Zeitbasis ist synchronisiert.</li>\n<li><code>kSyncToGateway</code> (2): Synchronisation erfolgt zu einem Gateway.</li>\n<li><code>kTimeLeapFuture</code> (3): Zeitsprung in die Zukunft festgestellt.</li>\n<li><code>kTimeLeapPast</code> (4): Zeitsprung in die Vergangenheit festgestellt.</li>\n<li><code>kHasDLS</code> (5): Daylight Saving Time (Sommerzeit) Information vorhanden.</li>\n<li><code>kDLSActive</code> (6): Daylight Saving Time (Sommerzeit) ist aktiv.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative C++-Datentypspezifikation für die Adaptive Platform Time Synchronization. Der Bezeichner <code>StatusFlag</code> definiert verbindlich den Enumerations-Typnamen, dessen ganzzahlige Belegungen (0 bis 6) in Schnittstellen zur Abfrage des Synchronisationsstatus einer Zeitbasis implementiert und referenziert werden müssen.</p>"}], "trans": [{"from": "FIG-ee034651ef5d8875", "to": "FIG-7ac4ab1084ae69e9", "fr": "R17-10_R1.2.0", "tr": "R18-03_R1.4.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Datentyp-Umbenennung: <code>StatusFlags</code> wurde in <code>StatusFlag</code> (Singular) umbenannt.</li>\n<li>Modellierungsrahmen: Das UML-Rahmenelement <code>class TimeBaseClassModel</code> ist entfallen; die Enumeration ist nun als eigenständiges Element dargestellt.</li>\n<li>Stereotyp: Die Stereotyp-Bezeichnung änderte sich von <code>«enumeration»</code> zu <code>«enum»</code>.</li>\n</ul>"}]};
